local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["6b064c8b4a263a50"] = { "%s stride chiedendo aiuto...", "." },
  ["6b076571461b833d"] = { "Merok! Shai! Al mio fianco!", "." },
  ["6b0c23d7863c48e2"] = { "<Benvenuto/Benvenuta> al Registro delle Gilde di ⟦Undercity=Sepulcra⟧. Che cosa vuoi?", "." },
  ["6b0c387fa28dec89"] = { "L'armatura della Redenzione era indossata dai nostri cavalieri più devoti: un'armatura degna dell'Araldo della Luce in persona!\n\nIn migliaia caddero nell'ultima guerra; le loro vesti furono strappate dai cadaveri e portate nella terribile cittadella di Naxxramas.\n\nSi dice che i cavalieri della morte di Naxxramas corrompano le piastre della Redenzione per il proprio uso.\n\nChe tragedia...", "." },
  ["6b0d1ada55a6ebed"] = { "Credo che mi riposerò un momento per riprendere fiato prima di tornare a ⟦Ratchet=Porto Paranco⟧. Grazie di tutto l'aiuto!", "." },
  ["6b14352f1e6b9619"] = { "Io mostro te quanto sono furbo, capo! Tu essere extra <furbo/furba> con potente mojo magico ora!\n\nUhm... forse Slip'kik usare magia su se stesso. Quella essere buona idea...", "." },
  ["6b148598ce29323d"] = { "Hai fatto molta strada, viandante. C'è un ultimo compito che devi svolgere...", "." },
  ["6b1d1e9344009a68"] = { "Il deserto di Tanaris è disseminato di ossa gigantesche proprio come questa alla mia destra. Non avrei mai voluto incontrare quella cosa.", "." },
  ["6b25e19553d6f32d"] = { "%s attacca un nuovo bersaglio!", "." },
  ["6b2860dc9533c56e"] = { "Eccolo! Spalancato. Buona fortuna nel conquistare ciò che c'è oltre. Devo fare subito rapporto al Kirin Tor!", "." },
  ["6b2d8e6107cc1e81"] = { "Non posso addestrarti.", "." },
  ["6b3b489ac46a5b11"] = { "Dov'ero rimasto? Ah sì, ci catturarono. Le mie guardie scelte furono giustiziate sul posto. Risparmiarono me e portarono via la principessa a dorso di montone. Mi condussero alle celle della Fossa delle Scorie e poi mi trasferirono in questa prigione.\n\nPosso solo supporre di essere ancora in vita perché vogliono estorcere un riscatto per la mia misera esistenza. O forse per crudeltà, per costringermi a rivivere per sempre nella mente gli eventi accaduti. Il rimpianto è il più crudele dei carcerieri, {race}.", "." },
  ["6b3f41007334484a"] = { "Hai visto cos'ho fatto? Se non sai bene come si esegue il /salute, esercitati con me. Se esegui correttamente il /Salute Shattered, ti darò la risposta adeguata.", "." },
  ["6b436d0db608002e"] = { "Davvero? È sempre stato il loro modo di agire. Cosa vale di più per Kel'Thuzad e per l'esercito sempre crescente del Flagello? Un seguace vivo e fanatico, capace di infiltrarsi in una società per poi scatenarvi una pestilenza che ne distrugge migliaia, o un singolo soldato non morto? Non puoi davvero essere così <ottuso/ottusa>\n\nSì, {race}, vivono, lavorano e tramano in mezzo a voi.", "." },
  ["6b49428429d922b6"] = { "Non è meraviglioso, bambini? Chiunque entri in città deve passare sotto lo sguardo vigile dei più grandi eroi delle nostre terre.", "." },
  ["6b4c08a713a52578"] = { "Attività dei ⟦Dark Iron=Ferroscuro⟧. Persino che alcune spedizioni sono state dirottate...", "." },
  ["6b537311e1c28f5b"] = { "I non morti banchetteranno con la tua anima, {name}.", "." },
  ["6b55e204d3174916"] = { "In che direzione posso indirizzarti?", "." },
  ["6b58010d0e91ba5f"] = { "⟦C'Thun=C'thun⟧ si riprenderà questo mondo!", "." },
  ["6b5ae9e1924a605b"] = { "Salve, Selarin. Temo di non poterti aiutare in questo momento, ma forse qualcuno degli avventurieri qui ad Auberdine può farlo...", "." },
  ["6b6aeea9c915413a"] = { "È una battaglia fredda e sanguinosa quella che combattiamo nella ⟦Alterac Valley=Valle d'Alterac⟧. Perfetta.", "." },
  ["6b6f4a0821040b2e"] = { "Poco dopo, cominciammo ad avere visioni di una creatura... Una creatura con le piume di un gufo, ma la volontà e la forza di un orso...", "." },
  ["6b7733fd8a3a6cac"] = { "Ha vinto il Blu! Complimenti, Blu!", "." },
  ["6b8877fc08d75f0c"] = { "Il maestro di gilda.", "." },
  ["6b925997d4748c7f"] = { "Ho la testa a posto quanto chiunque altro, <amico/amica>. Credi quello che vuoi, ma SONO in grado di realizzare questa armatura. Se ti interessa, forse possiamo metterci d'accordo. Prima esco dal giro degli assassinii, meglio è.", "." },
  ["6b95fb08c39a7711"] = { "Ora che la guerra è nel vivo, non ci sono mancati combattenti in forze dall'⟦Horde=Orda⟧ e dall'⟦Alliance=Alleanza⟧.\n\nSe solo riuscissimo a impedire che si saltino alla gola a vicenda...", "." },
  ["6b96648aa2547a4c"] = { "$966w Frostwolf Commander e $964w Frostwolf Lieutenant, soldato.", "." },
  ["6b999f5b6cac86a6"] = { "Salute, {class}. Per alcuni, la caccia è uno stile di vita, una professione scelta. Per altri è una specie di passatempo, un segno di coraggio o un rito di passaggio, a seconda della tribù.\n\nPer me razza e professione non significano nulla: ciò che rispetto è la prova del tuo spirito e della tua mente. Opporsi alle forze della natura e mettere alla prova tutte le proprie abilità è il vero segno dell'onore.\n\nSe vuoi metterti alla prova e guadagnarti il mio rispetto, parlami ancora.", "." },
  ["6ba33e5e05c681fe"] = { "Ricordi, Rajaxx, quando ti dissi che ti avrei ucciso per ultimo?", "." },
  ["6ba64689ee87c8a6"] = { "Hai quello che serve? Il tempo stringe!!", "." },
  ["6baa78226fcf5176"] = { "Vivere qui nel deserto è dura! Mi viene una sete tremenda a stare fuori con questo caldo.", "." },
  ["6baccfcf5351f5d9"] = { "Le erbe che si trovano in natura possono essere un potente alleato, se unite al rispetto. Per proseguire l'addestramento, cerca Bena nella sua bottega di alchimia sull'altura centrale.", "." },
  ["6bae7d6b4b1206f4"] = { "Ci siamo quasi!", "." },
  ["6bc1442f8a81ef18"] = { "Non così in fretta, <bello/bella>... Non affiderò le redini di un possente montone da sella a chi non si è dimostrato alleato dei nani di ⟦Ironforge=Forgiardente⟧. Quando la tua reputazione con ⟦Ironforge=Forgiardente⟧ sarà Amichevole, ti mostrerò volentieri le varietà di montoni che ho in vendita.", "." },
  ["6bd449449492abcd"] = { "Onore alla tua casa e ai tuoi antenati, {class}! Troverai ⟦Kartra Bloodsnarl=Kartra Ringhiorosso⟧ nella Hall of the Brave, nella ⟦Valley of Honor=Valle dell'Onore⟧.", "." },
  ["6be23911b2ba6cbc"] = { "Bene, credo di aver capito, ora. Seguimi, {name}!", "." },
  ["6be805af38b0c954"] = { "Naturalmente offro lezioni ad altri incantatori, purché siano pronti.", "." },
  ["6be87f89184fa502"] = { "Perché continui a dire che è morto? Chi ti ha detto che è morto? Non ho mai detto che è morto.\n\nÈ solo scomparso.\n\nVedi, a quanto pare eravamo finiti nel mezzo di una grossa battaglia tra orchi e nani ⟦Dark Iron=Ferroscuro⟧. Gli orchi, da quei luridi e miserabili bastardi che sono, erano usciti presto a piazzare trappole e altre diavolerie che probabilmente non capiresti.", "." },
  ["6bf31262ea0d9072"] = { "Sulle ali della morte io cavalco.", "." },
  ["6bf71d6d54579210"] = { "Se solo trovassi \"Magic and the Ways of Power\". Ahh, eccolo qui, che ci faceva da questa parte?", "." },
})
